FORMULA_COUNT = len(FORMULAS)
FORMULA_NAMES = tuple(f.name for f in FORMULAS)

def get_formula(name: str) -> FormulaInfo:
    """Return metadata for a public formula name."""
    for item in FORMULAS:
        if item.name == name: return item
    raise KeyError(name)

